mapper.select:
SELECT d.*,i.org_name ,ca.survey_case_no,ca.survey_person,info.entrust_org_name,info.survey_state_name FROM investigator_pre_details d LEFT JOIN survey_risk_case_info info on d.survey_info_id = info.id LEFT JOIN survey_risk_case ca ON ca.id = info.survey_id LEFT JOIN survey_investigator_case icase ON d.investigator_case_id = icase.id LEFT JOIN survey_investigator i ON icase.survey_user_id = i.user_id where info.delete_flag = 0 and d.investigator_re_id = #{id}
and FIND_IN_SET(i.org_id,#{orgId})
and FIND_IN_SET(i.user_id,#{surveyInvIds})

  SELECT d.investigator_case_id FROM investigator_re_details d LEFT JOIN investigator_re_info i ON d.investigator_re_id = i.id WHERE i.survey_user_id = #{userId}
  UNION
SELECT d.investigator_case_id  FROM investigator_pre_details d RIGHT JOIN survey_pre_reimbursement r ON d.investigator_re_id = r.id
WHERE r.survey_user_id = #{userId}

mapper.update:
update investigator_pre_details
set survey_info_id = #{surveyInfoId,jdbcType=BIGINT},
  investigator_re_id = #{investigatorReId,jdbcType=BIGINT},
  investigator_case_id = #{investigatorCaseId,jdbcType=BIGINT},
  Investigator_re_money = #{investigatorReMoney,jdbcType=DOUBLE}
where id = #{id,jdbcType=BIGINT}
